CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE projects(id TEXT PRIMARY KEY, created_at TEXT NOT NULL);
CREATE TABLE project_locations(identity_key TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id));
CREATE TABLE workspaces(project_id TEXT NOT NULL REFERENCES projects(id),id TEXT NOT NULL,root TEXT NOT NULL UNIQUE,identity_key TEXT NOT NULL,PRIMARY KEY(project_id,id));
CREATE TABLE workflows(project_id TEXT NOT NULL REFERENCES projects(id),id TEXT NOT NULL,binding_hash TEXT,host_identity TEXT,generation INTEGER NOT NULL CHECK(generation>0),active_context_id TEXT NOT NULL,PRIMARY KEY(project_id,id),UNIQUE(project_id,binding_hash),UNIQUE(project_id,host_identity));
CREATE TABLE contexts(project_id TEXT NOT NULL,id TEXT NOT NULL,workflow_id TEXT NOT NULL,workspace_id TEXT NOT NULL,session_id TEXT NOT NULL,generation INTEGER NOT NULL,connection_id TEXT NOT NULL,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id,workflow_id) REFERENCES workflows(project_id,id),FOREIGN KEY(project_id,workspace_id) REFERENCES workspaces(project_id,id));
CREATE TABLE attachment_receipts(project_id TEXT NOT NULL,binding_hash TEXT NOT NULL,request_id TEXT NOT NULL,payload_hash TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(project_id,binding_hash,request_id));
CREATE TABLE bootstrap_receipts(connection_id TEXT NOT NULL,request_id TEXT NOT NULL,payload_hash TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(connection_id,request_id));
CREATE TABLE tasks(project_id TEXT NOT NULL,id TEXT NOT NULL,goal TEXT NOT NULL,scope TEXT NOT NULL,workspace_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('in_progress','blocked','completed','abandoned')),parent_task_id TEXT,owner_workflow_id TEXT,ownership_epoch INTEGER NOT NULL CHECK(ownership_epoch>0),revision INTEGER NOT NULL CHECK(revision>0),latest_checkpoint_id TEXT,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id) REFERENCES projects(id),FOREIGN KEY(project_id,parent_task_id) REFERENCES tasks(project_id,id),FOREIGN KEY(project_id,owner_workflow_id) REFERENCES workflows(project_id,id));
CREATE TABLE checkpoints(project_id TEXT NOT NULL,id TEXT NOT NULL,task_id TEXT NOT NULL,sequence INTEGER NOT NULL,task_revision INTEGER NOT NULL,owner_workflow_id TEXT,ownership_epoch INTEGER NOT NULL,snapshot_json TEXT NOT NULL,service_observation_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(project_id,id),UNIQUE(project_id,task_id,sequence),FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id));
CREATE TABLE knowledge(project_id TEXT NOT NULL,id TEXT NOT NULL,key TEXT NOT NULL,scope_json TEXT NOT NULL,current_revision INTEGER NOT NULL,status TEXT NOT NULL,PRIMARY KEY(project_id,id),UNIQUE(project_id,key,scope_json),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE knowledge_revisions(project_id TEXT NOT NULL,id TEXT NOT NULL,revision INTEGER NOT NULL,claim TEXT,content_hash TEXT NOT NULL,status TEXT NOT NULL,metadata_json TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(project_id,id,revision),FOREIGN KEY(project_id,id) REFERENCES knowledge(project_id,id));
CREATE TABLE evidence(project_id TEXT NOT NULL,id TEXT NOT NULL,revision INTEGER NOT NULL,source_json TEXT NOT NULL,observation TEXT,content_hash TEXT NOT NULL,origin_observation_id TEXT NOT NULL,PRIMARY KEY(project_id,id,revision),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE checkpoint_knowledge_refs(project_id TEXT NOT NULL,checkpoint_id TEXT NOT NULL,object_id TEXT NOT NULL,revision INTEGER NOT NULL,ref_json TEXT NOT NULL,PRIMARY KEY(project_id,checkpoint_id,object_id,revision),FOREIGN KEY(project_id,checkpoint_id) REFERENCES checkpoints(project_id,id),FOREIGN KEY(project_id,object_id,revision) REFERENCES knowledge_revisions(project_id,id,revision));
CREATE TABLE checkpoint_evidence_refs(project_id TEXT NOT NULL,checkpoint_id TEXT NOT NULL,object_id TEXT NOT NULL,revision INTEGER NOT NULL,ref_json TEXT NOT NULL,PRIMARY KEY(project_id,checkpoint_id,object_id,revision),FOREIGN KEY(project_id,checkpoint_id) REFERENCES checkpoints(project_id,id),FOREIGN KEY(project_id,object_id,revision) REFERENCES evidence(project_id,id,revision));
CREATE TABLE events(seq INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL,entity_id TEXT NOT NULL,revision INTEGER NOT NULL,actor TEXT NOT NULL,request_id TEXT NOT NULL,kind TEXT NOT NULL,data_json TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE request_dedup(project_id TEXT NOT NULL,workflow_id TEXT NOT NULL,request_id TEXT NOT NULL,payload_hash TEXT NOT NULL,result_json TEXT,committed_at TEXT NOT NULL,versions_json TEXT NOT NULL,PRIMARY KEY(project_id,workflow_id,request_id),FOREIGN KEY(project_id,workflow_id) REFERENCES workflows(project_id,id));
CREATE VIRTUAL TABLE search_fts USING fts5(project_id UNINDEXED,doc_id UNINDEXED,revision UNINDEXED,body,tokenize='unicode61');
CREATE INDEX task_status_idx ON tasks(project_id,status,id);
CREATE INDEX checkpoint_task_idx ON checkpoints(project_id,task_id,sequence DESC);
CREATE TRIGGER checkpoint_immutable_update BEFORE UPDATE ON checkpoints BEGIN SELECT RAISE(ABORT,'immutable checkpoint');END;
CREATE TRIGGER checkpoint_immutable_delete BEFORE DELETE ON checkpoints BEGIN SELECT RAISE(ABORT,'immutable checkpoint');END;
CREATE TRIGGER knowledge_revision_immutable_update BEFORE UPDATE ON knowledge_revisions BEGIN SELECT RAISE(ABORT,'immutable knowledge revision');END;
CREATE TRIGGER knowledge_revision_immutable_delete BEFORE DELETE ON knowledge_revisions BEGIN SELECT RAISE(ABORT,'immutable knowledge revision');END;
CREATE TRIGGER evidence_immutable_update BEFORE UPDATE ON evidence BEGIN SELECT RAISE(ABORT,'immutable evidence');END;
CREATE TRIGGER evidence_immutable_delete BEFORE DELETE ON evidence BEGIN SELECT RAISE(ABORT,'immutable evidence');END;
